package com.zizai.watermark;

/** Reads currently playing sources, including addresses set after page load. */
final class WebMediaScanner {
    static String script(){return "(function(){var media=[];function add(u,k){if(typeof u==='string'&&u.indexOf('https://')===0&&media.length<48&&!media.some(x=>x.url===u&&x.kind===k))media.push({url:u,kind:k});}function scan(d){d.querySelectorAll('video,audio').forEach(x=>{var k=x.tagName==='AUDIO'?'AUDIO':'VIDEO';add(x.currentSrc,k);add(x.src,k);x.querySelectorAll('source').forEach(s=>add(s.src,k));});}scan(document);document.querySelectorAll('iframe').forEach(f=>{try{if(f.contentDocument)scan(f.contentDocument);}catch(e){}});performance.getEntriesByType('resource').slice(-128).forEach(x=>{try{var p=new URL(x.name).pathname.toLowerCase();if(/\\.(mp4|m4v|mov|webm|m3u8|mpd)$/.test(p))add(x.name,'VIDEO');else if(/\\.(mp3|m4a|aac|ogg|wav)$/.test(p))add(x.name,'AUDIO');}catch(e){}});var s=window.__INITIAL_STATE__||{},id=(location.pathname.match(/\\/(?:explore|discovery\\/item)\\/([a-f0-9]+)/)||[])[1],n=s.noteData&&s.noteData.data&&s.noteData.data.noteData;if(!n&&s.note&&s.note.noteDetailMap&&id)n=(s.note.noteDetailMap[id]||{}).note;return JSON.stringify({html:Array.from(document.querySelectorAll('title,meta,video,audio,source,script[type=\"application/ld+json\"]')).map(x=>x.outerHTML).join(''),state:n?JSON.stringify({noteData:{data:{noteData:n}}}):'',media:media});})()";}
}
